/** `err`, thrown across the boundary. */
class ErrException(val error: Err) : kotlin.Exception(errMessage(error))

private fun errMessage(error: Err): String = when (error) {
    is Err.TypeError -> error.value.toString()
    is Err.Error -> error.value.toString()
}

/** `e` as `err`: its own error, or the fallback arm with its message. */
fun toErr(e: kotlin.Throwable): Err = if (e is ErrException) e.error else Err.Error((e.message ?: e.toString()).toJsString())

fun raiseErr(e: kotlin.js.JsException): ErrException {
    val r1 = fixtures.union_params.flat.err_err(e.thrownValue)
    val s2 = fixtures.union_params.flat.ret_externref()
    return ErrException(decodeErr(r1, s2)!!)
}

fun futureErrorErr(f: JsAny): ErrException {
    val r2 = fixtures.union_params.flat.error_err(f)
    val s3 = fixtures.union_params.flat.ret_externref()
    return ErrException(decodeErr(r2, s3)!!)
}

fun setErr(e: kotlin.Throwable) {
    val w = encodeErr(toErr(e))
    fixtures.union_params.flat.err_set_err(w.arm, w.s0)
}

